package com.aistock.prediction.comparisonai;
import com.aistock.prediction.comparison.ComparisonRepository;import com.aistock.prediction.explanation.MaasClient;import com.aistock.common.BusinessException;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static com.aistock.prediction.comparisonai.ComparisonAiSamples.*;
class ComparisonAiServiceTest {
 final Clock clock=Clock.fixed(Instant.parse("2026-10-13T00:00:00Z"),ZoneOffset.UTC);final UUID owner=UUID.randomUUID();final ComparisonAiInput input=new ComparisonAiInput(UUID.randomUUID(),ID);
 @Test void disabledFlagCannotCallProviderButTerminalReplayRemainsAvailable(){var records=mock(ComparisonAiRepository.class);var source=mock(ComparisonRepository.class);var client=mock(MaasClient.class);when(source.get(owner,ID)).thenReturn(saved());var service=new ComparisonAiService(records,source,client,M,clock,false);assertEquals("AI_NOT_CONFIGURED",assertThrows(BusinessException.class,()->service.generate(owner,input)).code());verify(records,never()).claim(any(),any(),any(),any());verifyNoInteractions(client);var terminal=M.createObjectNode().put("state","SUCCEEDED");when(records.replay(eq(owner),eq(input),any())).thenReturn(terminal);assertTrue(service.generate(owner,input).replayed());verifyNoInteractions(client);}
 @Test void invalidModelOutputIsPersistedFailureAndGetDoesNotGenerate(){var records=mock(ComparisonAiRepository.class);var source=mock(ComparisonRepository.class);var client=mock(MaasClient.class);when(source.get(owner,ID)).thenReturn(saved());when(client.enabled()).thenReturn(true);when(client.model()).thenReturn("fixture");when(records.claim(eq(owner),eq(input),any(),any())).thenReturn(new ComparisonAiRepository.Claim(true,M.createObjectNode().put("state","RUNNING"),false,false));when(client.generateComparison(anyMap())).thenReturn(M.createObjectNode());when(records.complete(eq(owner),eq(input.operationId()),isNull(),eq("AI_OUTPUT_INVALID"),any())).thenReturn(M.createObjectNode().put("state","FAILED"));var service=new ComparisonAiService(records,source,client,M,clock,true);assertEquals("FAILED",service.generate(owner,input).operation().path("state").asText());service.view(owner,ID);service.operation(owner,input.operationId());verify(client,times(1)).generateComparison(anyMap());}
}
